"@import "tailwindcss";

@layer base {
  * {
    -webkit-tap-highlight-color: transparent;
    box-sizing: border-box;
  }
  body {
    font-family: 'Chakra Petch', sans-serif;
    touch-action: manipulation;
  }
}

.font-gta-hud {
  font-family: 'Rajdhani', 'Chakra Petch', sans-serif;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.font-gta-title {
  font-family: 'Orbitron', 'Chakra Petch', sans-serif;
  letter-spacing: 0.1em;
}

.font-pixel {
  font-family: 'Press Start 2P', cursive;
}

/* Effet néon & Glow GTA / Cyber */
.glow-gta-yellow {
  box-shadow: 0 0 15px rgba(250, 204, 21, 0.6), inset 0 0 10px rgba(250, 204, 21, 0.3);
}

.glow-gta-purple {
  box-shadow: 0 0 15px rgba(168, 85, 247, 0.7);
}

.text-glow-yellow {
  text-shadow: 0 0 10px rgba(250, 204, 21, 0.8), 0 0 20px rgba(250, 204, 21, 0.4);
}

/* Radar scanline subtil */
.radar-scanline {
  background: linear-gradient(
    rgba(18, 16, 16, 0) 50%, 
    rgba(0, 0, 0, 0.25) 50%
  ), linear-gradient(
    90deg,
    rgba(255, 0, 0, 0.03),
    rgba(0, 255, 0, 0.01),
    rgba(0, 0, 255, 0.03)
  );
  background-size: 100% 3px, 6px 100%;
}

/* Animations de clignotement pour les étoiles de recherche */
@keyframes star-flash {
  0%, 100% { opacity: 1; filter: drop-shadow(0 0 8px #ef4444); }
  50% { opacity: 0.2; filter: none; }
}

.animate-star-wanted {
  animation: star-flash 0.8s ease-in-out infinite;
}

/* Masquer les contrôles MapLibre natifs non désirés */
.maplibregl-ctrl-attrib {
  opacity: 0.3;
  font-size: 9px;
  background: transparent !important;
}
.maplibregl-ctrl-attrib:hover {
  opacity: 0.8;
}
"

