"async function run() {
  const pagesRes = await fetch('http://127.0.0.1:9222/json');
  const pages = await pagesRes.json();
  const page = pages.find(p => p.type === 'page');
  if (!page) {
    console.error('No page found');
    process.exit(1);
  }

  const ws = new WebSocket(page.webSocketDebuggerUrl);

  await new Promise((resolve) => ws.onopen = resolve);

  let reqId = 1;
  function evaluate(expr) {
    return new Promise((resolve) => {
      const id = reqId++;
      const handler = (evt) => {
        const data = JSON.parse(evt.data);
        if (data.id === id) {
          ws.removeEventListener('message', handler);
          resolve(data.result?.result?.value);
        }
      };
      ws.addEventListener('message', handler);
      ws.send(JSON.stringify({
        id,
        method: 'Runtime.evaluate',
        params: { expression: expr, returnByValue: true, awaitPromise: true }
      }));
    });
  }

  console.log('--- TEST 1: Initial Zoom ---');
  const initialZoom = await evaluate('window.carMap ? window.carMap.getZoom() : null');
  console.log('Initial zoom:', initialZoom);

  console.log('--- TEST 2: Simulating manual zoom out (user zooms to 12.0) ---');
  // Simulate user changing zoom to 12.0 (e.g. pinch to zoom out)
  // We trigger zoom on map
  await evaluate('window.carMap.zoomTo(12, { duration: 200 })');
  await new Promise(r => setTimeout(r, 600));
  const zoomedOut = await evaluate('window.carMap.getZoom()');
  console.log('Zoom after manual zoom-out:', zoomedOut);

  console.log('--- TEST 3: User clicks Recentrer button ---');
  // Let's click the recenter button in the DOM
  await evaluate(`
    const btn = document.querySelector('button[title*="Recentrer"]');
    if (btn) btn.click();
  `);
  // Wait for 800ms recenter animation
  await new Promise(r => setTimeout(r, 1200));

  const recenteredZoom = await evaluate('window.carMap.getZoom()');
  console.log('Zoom after clicking Recentrer:', recenteredZoom);

  ws.close();
}
