58: export async function searchLocations(query: string): Promise<LocationSearchResult[]> {
59:   if (!query || query.trim().length < 2) {
60:     return PRESET_DESTINATIONS;
61:   }
62: 
63:   try {
64:     const encoded = encodeURIComponent(query.trim());
65:     // Priorité géographique sur la Gironde / Sud-Ouest (lat ~ 44.8, lon ~ -0.5)
66:     const url = `https://photon.komoot.io/api/?q=${encoded}&lat=44.8378&lon=-0.5792&limit=5`;
67:     const response = await fetch(url);
68: 
69:     if (!response.ok) {
70:       return PRESET_DESTINATIONS.filter(p => 
71:         p.name.toLowerCase().includes(query.toLowerCase()) || 
72:         p.label.toLowerCase().includes(query.toLowerCase())
73:       );
74:     }
75: 
76:     const data = await response.json();
77:     if (!data.features || data.features.length === 0) {
78:       return [];
79:     }
80: 
81:     return data.features.map((f: any) => {
82:       const props = f.properties;
83:       const parts = [props.name, props.street, props.city, props.country].filter(Boolean);
84:       return {
85:         name: props.name || props.street || 'Point de repère',
86:         label: parts.join(', '),
87:         city: props.city || 'Gironde',
88:         country: props.country || 'France',
89:         coordinates: f.geometry.coordinates as Coordinates,
90:       };
91:     });
92:   } catch (error) {
93:     console.warn('Erreur geocoding Photon, fallback', error);
94:     return PRESET_DESTINATIONS.filter(p => 
