  vehicleType = 'arrow_gta',
  vehicleColor = '#facc15',
  showHeadlights = true,
  onMapLongPress,
  onUserMove,
}) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const playerMarkerRef = useRef<maplibregl.Marker | null>(null);"

