"  // Curseur joueur selon le jeu
  const getMarkerHtml = (type: 'gta' | 'minecraft' | 'waze') => {
    if (type === 'minecraft') {
      // Le curseur exact de la photo (flèche blanche avec contour noir pixelisé)
      return `
        <div id="player-arrow" class="w-14 h-14 flex items-center justify-center transition-transform duration-100 ease-linear">
          <img src="/textures/minecraft_cursor.png" class="w-12 h-12 object-contain drop-shadow-[0_4px_10px_rgba(0,0,0,0.9)]" style="image-rendering: pixelated;" />
        </div>
      `;
    }

    if (type === 'waze') {
      return `
        <div id="player-arrow" class="w-12 h-12 flex items-center justify-center transition-transform duration-100 ease-linear">
          <svg viewBox="0 0 24 24" class="w-10 h-10 drop-shadow-[0_3px_10px_rgba(0,0,0,0.8)]">
            <path d="M12 2L4 21L12 17L20 21L12 2Z" fill="#38bdf8" stroke="#ffffff" stroke-width="2" stroke-linejoin="round" />
          </svg>
        </div>
      `;
    }

    // Curseur Radar GTA V original (Flèche jaune)
    return `
      <div id="player-arrow" class="w-12 h-12 flex items-center justify-center transition-transform duration-100 ease-linear">
        <svg viewBox="0 0 24 24" class="w-11 h-11 drop-shadow-[0_3px_12px_rgba(0,0,0,0.95)]">
          <path d="M12 2L4 21L12 17L20 21L12 2Z" fill="#facc15" stroke="#000000" stroke-width="2.5" stroke-linejoin="round" />
        </svg>
      </div>
    `;
  };"

