      [this.position[0], this.position[1]],
      0
    );

    const baseMeterScale = coord.meterInMercatorCoordinateUnits();

    // Adaptive scale so the vehicle looks great at any zoom
    // Standard cars are ~4.8m long. We scale dynamically from street level up to high altitude
    const currentZoom = this.map.getZoom();
    let zoomMultiplier = 2.0; // 2x gives a prominent video-game / navigation feel on road
    if (currentZoom < 17) {
      zoomMultiplier = 2.0 * Math.pow(1.3, 17 - currentZoom);
    }
    // Cap multiplier to avoid gigantic vehicle when zoomed out to country view
    zoomMultiplier = Math.min(zoomMultiplier, 12.0);

    const finalScale = baseMeterScale * zoomMultiplier;

    // MapLibre's matrix converts Mercator coordinates (0..1) to screen
    const m = new THREE.Matrix4().fromArray(matrix);"

