const THREE = require('three');
const length = 6.0;
const heightY = 0.55;
const frontZ = 2.3;
const targetEndY = 0.05;

// We want:
// Start of beam: at (x, heightY, frontZ), radius = 0.06
// End of beam: at (x, targetEndY, frontZ + length), radius = 0.85

// With CylinderGeometry(radiusTop, radiusBottom, length):
// In local coords, Top is at +length/2, Bottom is at -length/2.

// If we put radiusTop = 0.06 (narrow) and radiusBottom = 0.85 (wide):
// We want Top (+length/2) to end up at (heightY, frontZ)
// and Bottom (-length/2) to end up at (targetEndY, frontZ + length)

// Vector from start to end:
const dir = new THREE.Vector3(0, targetEndY - heightY, length);
console.log('Target vector:', dir);

// Let's test a simple translation on the geometry itself or rotation:
// If we rotate a vector (0, -1, 0) - which points from Top to Bottom:
// We want (0, -1, 0) to align with dir.clone().normalize()!
const vCylinder = new THREE.Vector3(0, -1, 0); // from top to bottom
const q = new THREE.Quaternion().setFromUnitVectors(vCylinder, dir.clone().normalize());
const euler = new THREE.Euler().setFromQuaternion(q);
console.log('Euler angles:', euler.x, euler.y, euler.z);

// Let's test with this quaternion/rotation:
const mesh = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.85, length, 16, 1, true));
mesh.setRotationFromEuler(euler);
mesh.position.set(0, (heightY + targetEndY) / 2, frontZ + length / 2);
mesh.updateMatrixWorld();

const pTop = new THREE.Vector3(0, length / 2, 0).applyMatrix4(mesh.matrixWorld);
const pBottom = new THREE.Vector3(0, -length / 2, 0).applyMatrix4(mesh.matrixWorld);
console.log('Result Top (start, narrow):', pTop);
console.log('Result Bottom (end, wide):', pBottom);
