const THREE = require('three');
const length = 6.0;
const heightY = 0.55;
const frontZ = 2.3;
const targetEndY = 0.05;

// If we translate geometry so that top is at (0, 0, 0)
const geo = new THREE.CylinderGeometry(0.06, 0.85, length, 16, 1, true);
// In cylinder, top is at +length/2. So translating by -length/2 puts the narrow tip at (0, 0, 0):
geo.translate(0, -length / 2, 0);

// Now the beam starts at local (0, 0, 0) and extends down along -Y to (0, -length, 0)!
// If we rotate: we want vector (0, -1, 0) to point towards (0, targetEndY - heightY, length):
const dir = new THREE.Vector3(0, targetEndY - heightY, length).normalize();
const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, -1, 0), dir);

const mesh = new THREE.Mesh(geo);
mesh.setRotationFromQuaternion(q);
mesh.position.set(-0.75, heightY, frontZ);
mesh.updateMatrixWorld();

