const THREE = require('three');

function createHeadlightBeams(
  spread,
  length,
  frontZ = 2.3,
  heightY = 0.55,
  isSingle = false
) {
  const group = new THREE.Group();
  const roadY = 0.04;

  const beamRadiusStart = isSingle ? 0.09 : 0.05;
  const beamRadiusEnd = isSingle ? spread * 0.9 : spread * 0.55;

  const beamGeo = new THREE.CylinderGeometry(
    beamRadiusStart,
    beamRadiusEnd,
    length,
    16,
    1,
    true
  );
  beamGeo.translate(0, -length / 2, 0);

  const beamMat = new THREE.MeshBasicMaterial({
    color: 0xfff6cf,
    transparent: true,
    opacity: 0.22,
    depthWrite: false,
    side: THREE.DoubleSide,
    blending: THREE.AdditiveBlending,
  });

  const vDown = new THREE.Vector3(0, -1, 0);

  if (isSingle) {
    const dir = new THREE.Vector3(0, roadY - heightY, length).normalize();
    const q = new THREE.Quaternion().setFromUnitVectors(vDown, dir);
    const beam = new THREE.Mesh(beamGeo, beamMat);
    beam.setRotationFromQuaternion(q);
    beam.position.set(0, heightY, frontZ);
    group.add(beam);
  } else {
    // Left beam
    const startXLeft = -spread * 0.48;
    const dirLeft = new THREE.Vector3(-0.25, roadY - heightY, length).normalize();
    const qLeft = new THREE.Quaternion().setFromUnitVectors(vDown, dirLeft);
    const leftBeam = new THREE.Mesh(beamGeo, beamMat);
    leftBeam.setRotationFromQuaternion(qLeft);
    leftBeam.position.set(startXLeft, heightY, frontZ);
    group.add(leftBeam);

    // Right beam
    const startXRight = spread * 0.48;
    const dirRight = new THREE.Vector3(0.25, roadY - heightY, length).normalize();
    const qRight = new THREE.Quaternion().setFromUnitVectors(vDown, dirRight);
    const rightBeam = new THREE.Mesh(beamGeo, beamMat);
    rightBeam.setRotationFromQuaternion(qRight);
    rightBeam.position.set(startXRight, heightY, frontZ);
    group.add(rightBeam);
  }

  return group;
}

